-- 取回 meas
WITH [base] AS (SELECT [ds_orders].[Row ID] AS [f_row_id], [ds_orders].[Order ID] AS [f_order_id], [ds_orders].[Order Date] AS [f_order_date], [ds_orders].[Ship Date] AS [f_ship_date], [ds_orders].[Ship Mode] AS [f_ship_mode], [ds_orders].[Customer ID] AS [f_customer_id], [ds_orders].[Customer Name] AS [f_customer_name], [ds_orders].[Segment] AS [f_segment], [ds_orders].[Country/Region] AS [f_country_region], [ds_orders].[City] AS [f_city], [ds_orders].[State/Province] AS [f_state_province], [ds_orders].[Postal Code] AS [f_postal_code], [ds_orders].[Region] AS [f_region], [ds_orders].[Product ID] AS [f_product_id], [ds_orders].[Category] AS [f_category], [ds_orders].[Sub-Category] AS [f_sub_category], [ds_orders].[Product Name] AS [f_product_name], [ds_orders].[Sales] AS [f_sales], [ds_orders].[Quantity] AS [f_quantity], [ds_orders].[Discount] AS [f_discount], [ds_orders].[Profit] AS [f_profit] FROM [dbo].[ds_orders] AS [ds_orders]), [src] AS (SELECT * FROM [base] WHERE ([f_country_region] IN ('United States'))), [topn_agg] AS (SELECT [f_customer_name] AS [__k0], SUM([f_sales]) AS [__a0] FROM [src] GROUP BY [f_customer_name]), [topn] AS (SELECT TOP 10 [__k0] AS [__member] FROM [topn_agg] ORDER BY [__a0] DESC, CASE WHEN [__k0] IS NULL THEN 1 ELSE 0 END, [__k0] ASC), [sets_ext] AS (SELECT *, CAST(CASE WHEN EXISTS(SELECT 1 FROM [topn] WHERE ([topn].[__member] = [f_customer_name] OR [topn].[__member] IS NULL AND [f_customer_name] IS NULL)) THEN 1 WHEN NOT EXISTS(SELECT 1 FROM [topn] WHERE ([topn].[__member] = [f_customer_name] OR [topn].[__member] IS NULL AND [f_customer_name] IS NULL)) THEN 0 END AS BIT) AS [__set_0] FROM [src]), [dimf] AS (SELECT * FROM [sets_ext] WHERE ([f_region] IS NULL OR NOT ([f_region] IN ('Central')))), [agg] AS (SELECT [__set_0] AS [__k0], SUM([f_sales]) AS [__a0], COUNT_BIG(DISTINCT [f_customer_name]) AS [__a1] FROM [dimf] GROUP BY [__set_0]), [meas] AS (SELECT *, [__a0] AS [__m0], [__a1] AS [__m1] FROM [agg]) SELECT * FROM [meas]
